const msg = ($input.first().json.message?.text || '').trim().toLowerCase();
const chatId = $input.first().json.message?.chat?.id || '';
let type = 'other';
let originalText = $input.first().json.message?.text || '';

if (msg === 'approve' || msg === 'موافق') type = 'approve';
else if (msg === 'export' || msg === 'صدر' || msg === 'تصدير') type = 'export';
else if (msg === 'post' || msg === 'انشر' || msg === 'نشر') type = 'post';
else if (msg === 'أخبار' || msg === 'اخبار' || msg === 'news') type = 'news';
else if (/^\d+$/.test(msg) && parseInt(msg) >= 1 && parseInt(msg) <= 10) {
  const pickNum = parseInt(msg);
  const staticData = $getWorkflowStaticData('global');
  const cached = staticData.newsCache;
  const cacheAge = Date.now() - (staticData.newsCacheAt || 0);
  if (cached && cacheAge < 3600000 && pickNum <= cached.length) {
    const chosen = cached[pickNum - 1];
    let fullContent = '';
    try {
      const page = await this.helpers.httpRequest({ method: 'GET', url: chosen.link, headers: { 'Accept': 'text/html' } });
      let body = page;
      const articleMatch = body.match(/<article[^>]*>(.*?)<\/article>/s) || body.match(/<div[^>]*class="[^"]*(?:entry-content|post-content|article-content|content-area)[^"]*"[^>]*>(.*?)<\/div>/s);
      if (articleMatch) body = articleMatch[1];
      body = body.replace(/<script[^>]*>.*?<\/script>/gs, '').replace(/<style[^>]*>.*?<\/style>/gs, '').replace(/<[^>]*>/g, ' ').replace(/&[^;]+;/g, ' ').replace(/\s+/g, ' ').trim();
      fullContent = body.substring(0, 2000);
    } catch(e) { fullContent = chosen.desc; }
    originalText = 'اكتب كاروسيل عن هالخبر. لخص النقاط المهمة واذا في خطوات وضحها بشكل مختصر:\n\nالعنوان: ' + chosen.title + '\n\nالمحتوى الكامل:\n' + fullContent + '\n\nالمصدر: ' + chosen.link;
    type = 'topic';
    return [{ json: { type, originalText, chatId } }];
  }
  // Fallback: re-fetch if no cache
  const RSS_FEEDS = [
  '__YOUR_RSS_FEED_1__',
  '__YOUR_RSS_FEED_2__',
  '__YOUR_RSS_FEED_3__',
  '__YOUR_RSS_FEED_4__',
  '__YOUR_RSS_FEED_5__',
  '__YOUR_RSS_FEED_6__',
  '__YOUR_RSS_FEED_7__',
  '__YOUR_RSS_FEED_8__',
  '__YOUR_RSS_FEED_9__',
  '__YOUR_RSS_FEED_10__'
];
  const allArticles = [];
  for (const feedUrl of RSS_FEEDS) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET', url: feedUrl,
        headers: { 'Accept': 'application/rss+xml, application/xml, text/xml' }
      });
      const xml = typeof res === 'string' ? res : JSON.stringify(res);
      const items = xml.split('<item>').slice(1, 8);
      for (const item of items) {
        const titleMatch = item.match(/<title><!\[CDATA\[(.+?)\]\]>|<title>(.+?)<\/title>/);
        const linkMatch = item.match(/<link>(.+?)<\/link>|<link><!\[CDATA\[(.+?)\]\]>/);
        const descMatch = item.match(/<description><!\[CDATA\[(.+?)\]\]>|<description>(.+?)<\/description>/s);
        const dateMatch = item.match(/<pubDate>(.+?)<\/pubDate>/);
        const contentMatch = item.match(/<content:encoded><!\[CDATA\[(.+?)\]\]>/s);
        const title = (titleMatch ? (titleMatch[1] || titleMatch[2]) : '').trim();
        const link = (linkMatch ? (linkMatch[1] || linkMatch[2]) : '').trim();
        let desc = (descMatch ? (descMatch[1] || descMatch[2]) : '').trim();
        desc = desc.replace(/<[^>]*>/g, '').replace(/&[^;]+;/g, ' ').substring(0, 120).trim();
        const pubDate = dateMatch ? new Date(dateMatch[1]).getTime() : 0;
        const source = feedUrl.includes('socialmediaexaminer') ? 'SME' : feedUrl.includes('anthropic') ? 'Anthropic' : feedUrl.includes('openai') ? 'OpenAI' : feedUrl.includes('venturebeat') ? 'VB' : feedUrl.includes('theverge') ? 'Verge' : feedUrl.includes('later') ? 'Later' : feedUrl.includes('techcrunch') ? 'TC' : feedUrl.includes('buffer') ? 'Buffer' : 'WERSM';
        const aiSources = ['Anthropic','OpenAI','VB','Verge','TC-AI']; const isAI = aiSources.includes(source); const isInstagram = isAI || source !== 'Buffer' || (title + ' ' + desc).toLowerCase().includes('instagram') || (title + ' ' + desc).toLowerCase().includes('reels') || (title + ' ' + desc).toLowerCase().includes('meta');
        if (title && link && isInstagram) allArticles.push({ title, link, desc, pubDate, source });
      }
    } catch (e) {}
  }
  allArticles.sort((a, b) => b.pubDate - a.pubDate);
  const top5 = allArticles.slice(0, 10);
  if (pickNum <= top5.length) {
    const chosen = top5[pickNum - 1];

    // Fetch full article content
    let fullContent = '';
    try {
      const page = await this.helpers.httpRequest({
        method: 'GET', url: chosen.link,
        headers: { 'Accept': 'text/html' }
      });
      // Extract text from article body
      let body = page;
      // Try to find article/post content area
      const articleMatch = body.match(/<article[^>]*>(.*?)<\/article>/s) || 
                           body.match(/<div[^>]*class="[^"]*(?:entry-content|post-content|article-content|content-area)[^"]*"[^>]*>(.*?)<\/div>/s);
      if (articleMatch) body = articleMatch[1];
      // Remove scripts, styles, tags
      body = body.replace(/<script[^>]*>.*?<\/script>/gs, '');
      body = body.replace(/<style[^>]*>.*?<\/style>/gs, '');
      body = body.replace(/<[^>]*>/g, ' ');
      body = body.replace(/&[^;]+;/g, ' ');
      body = body.replace(/\s+/g, ' ').trim();
      fullContent = body.substring(0, 2000);
    } catch (e) {
      fullContent = chosen.desc;
    }

    originalText = 'اكتب كاروسيل عن هالخبر. لخص النقاط المهمة واذا في خطوات وضحها بشكل مختصر:\n\nالعنوان: ' + chosen.title + '\n\nالمحتوى الكامل:\n' + fullContent + '\n\nالمصدر: ' + chosen.link;
    type = 'topic';
  }
}
else if (/^s\d+:/i.test(msg) || /^caption:/i.test(msg) || /^hashtags:/i.test(msg)) type = 'edit';
else if (msg.length > 2) type = 'topic';

return [{ json: { type, originalText, chatId } }];

function extractText(value) {
  // نص عادي
  if (typeof value === 'string') {
    return value;
  }

  // مصفوفة Claude content blocks
  if (Array.isArray(value)) {
    const textBlock = value.find(
      block =>
        block &&
        block.type === 'text' &&
        typeof block.text === 'string'
    );

    return textBlock?.text || '';
  }

  // كائن يحتوي على content
  if (value && typeof value === 'object') {
    if (typeof value.text === 'string') {
      return value.text;
    }

    if (value.content !== undefined) {
      return extractText(value.content);
    }
  }

  return '';
}

let raw = '';

// أولًا: نحاول قراءة النص المحفوظ في Google Sheets
try {
  const sheetData = $('Save to Sheet').first().json;
  raw = extractText(sheetData.content);
} catch (error) {
  raw = '';
}

// إذا لم يوجد نص صالح في الجدول، نقرأ مباشرة من Claude
if (!raw) {
  try {
    const claudeResponse = $('Claude Content API1').first().json;
    raw = extractText(claudeResponse.content);
  } catch (error) {
    raw = '';
  }
}

// Fallback من مدخل العقدة الحالي
if (!raw) {
  raw = extractText($input.first().json);
}

if (!raw || typeof raw !== 'string') {
  throw new Error(
    'لم يتم العثور على النص النهائي في رد Claude. تأكد أن الرد يحتوي على block من النوع text.'
  );
}

// تنظيف code fences في حال رجع JSON داخل Markdown
raw = raw
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');

if (start === -1 || end === -1 || end <= start) {
  throw new Error(
    'رد Claude لا يحتوي على JSON صالح.\n\nبداية الرد:\n' +
    raw.slice(0, 500)
  );
}

let content;

try {
  content = JSON.parse(raw.slice(start, end + 1));
} catch (error) {
  throw new Error(
    'تعذر تحليل JSON الصادر من Claude: ' +
    error.message +
    '\n\nبداية الرد:\n' +
    raw.slice(0, 700)
  );
}

if (!Array.isArray(content.slides) || content.slides.length === 0) {
  throw new Error('JSON صالح، لكن لا توجد سلايدات داخل slides.');
}

const topic = content.topic || 'موضوع جديد';
const slideCount = content.slides.length;

let preview = '✅ تم إنشاء المحتوى!\n\n';
preview += '📌 الموضوع: ' + topic + '\n';
preview += '🔢 عدد السلايدات: ' + slideCount + '\n\n';

content.slides.forEach((s, i) => {
  preview += '━━━ سلايد ' + (i + 1) + ' (' + (s.type || 'unknown') + ') ━━━\n';

  if (s.type === 'cover') {
    if (s.eyebrow) {
      preview += s.eyebrow + '\n';
    }

    preview += [
      s.title_line1,
      s.title_line2_grad,
      s.title_line3
    ]
      .filter(Boolean)
      .join(' ') + '\n';

    if (s.pill) {
      preview += '🏷 ' + s.pill + '\n';
    }
  }

  else if (s.type === 'stat') {
    preview += '🔢 ' + (s.number || '') + '\n';
    preview += '📍 ' + (s.label || '') + '\n';

    if (s.description) {
      preview += s.description + '\n';
    }
  }

  else if (s.type === 'how_to') {
    preview += '📝 ' + (s.title || '') + '\n';

    (s.steps || []).forEach((step, j) => {
      preview += (j + 1) + '. ' + step + '\n';
    });
  }

  else if (s.type === 'why_matters') {
    preview += '💡 ' + (s.title || '') + '\n';

    (s.points || []).forEach((point, j) => {
      preview += (j + 1) + '. ' + point + '\n';
    });
  }

  else if (s.type === 'save') {
    preview += '🔖 احفظ هالمعلومات:\n';

    (s.points || []).forEach((point, j) => {
      preview += (j + 1) + '. ' + point + '\n';
    });
  }

  else if (s.type === 'warning') {
    preview += '⚠️ ' + (s.title || 'انتبه!') + '\n';

    (s.points || []).forEach((point, j) => {
      preview += (j + 1) + '. ' + point + '\n';
    });
  }

  else if (s.type === 'one_liner') {
    preview += '💬 ' + (s.text || '') + '\n';
  }

  else if (s.type === 'quote') {
    preview += '💬 "' + (s.quote || '') + '"\n';

    if (s.author) {
      preview += '— ' + s.author;

      if (s.role) {
        preview += ' (' + s.role + ')';
      }

      preview += '\n';
    }
  }

  else if (s.type === 'comparison') {
    preview +=
      (s.col1_header || 'الأول') +
      ' vs ' +
      (s.col2_header || 'الثاني') +
      '\n';

    (s.rows || []).forEach(row => {
      if (Array.isArray(row)) {
        preview +=
          '• ' +
          (row[0] || '') +
          ' | ' +
          (row[1] || '') +
          '\n';
      }
    });
  }

  else if (s.type === 'action_prompt') {
    preview += '📣 ' + (s.headline || '') + '\n';
    preview += 'الإجراء: ' + (s.action || 'save') + '\n';
  }

  else if (s.type === 'cta') {
    preview += '❓ ' + (s.question || '') + '\n';

    if (
      Array.isArray(s.options) &&
      s.options.length
    ) {
      s.options.forEach((option, j) => {
        preview +=
          String.fromCharCode(65 + j) +
          ') ' +
          option +
          '\n';
      });
    }

    else if (s.cta_style === 'poll') {
      preview +=
        'A) ' + (s.poll_left || 'موافق') + '\n';

      preview +=
        'B) ' + (s.poll_right || 'مو موافق') + '\n';
    }
  }

  preview += '\n';
});

if (content.caption) {
  preview +=
    '━━━ الكابشن ━━━\n' +
    content.caption +
    '\n\n';
}

if (content.hashtags) {
  preview +=
    '━━━ الهاشتاقات ━━━\n' +
    content.hashtags +
    '\n\n';
}

preview +=
  '💬 أرسل approve للتصميم\n\n' +
  '✏️ أو عدّل:\n' +
  's2: قديم > جديد\n' +
  'caption: نص جديد';

return [
  {
    json: {
      preview,
      chatId: $('Telegram Trigger').first().json.message.chat.id,
      contentJson: JSON.stringify(content),
      topic,
      slideCount,
      caption: content.caption || '',
      hashtags: content.hashtags || ''
    }
  }
];

const items = $input.all();
let lastDraft = null;
let lastIndex = -1;
for (let i = items.length - 1; i >= 0; i--) {
  if (items[i].json.status === 'draft') {
    lastDraft = items[i].json;
    lastIndex = i + 2; // +2 because sheets are 1-indexed and header row
    break;
  }
}
if (!lastDraft) throw new Error('No draft rows found');
return [{ json: { ...lastDraft, rowIndex: lastIndex, contentJson: lastDraft['content'] } }];

let raw = $('Get Last Draft').item.json.contentJson;
let start = raw.indexOf('{');
let end = raw.lastIndexOf('}');
const data = JSON.parse(raw.substring(start, end + 1));
const slides = data.slides;
const N = slides.length;
const MAJED_PHOTO = "data:image/svg+xml;base64,";

const CSS = `@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;700;900&display=swap');
* { margin: 0; padding: 0; box-sizing: border-box; }
