function progressBar(idx, total) {
  let segs = '';
  for (let i = 0; i < total; i++) {
    segs += '<div class="seg' + (i <= idx ? ' done' : '') + '"></div>';
  }
  return '<div class="progress">' + segs + '</div>';
}

function counter(idx, total) {
  return '<div class="counter">' + (idx+1) + ' / ' + total + '</div>';
}

function dots(idx, total) {
  let d = '';
  for (let i = 0; i < total; i++) {
    d += '<div class="dot' + (i === idx ? ' active' : '') + '"></div>';
  }
  return '<div class="dots">' + d + '</div>';
}

function ltr(text) {
  return '<span style="unicode-bidi:embed;direction:ltr">' + text + '</span>';
}

function renderSlide(slide, idx) {
  const common = progressBar(idx, N) + counter(idx, N) + dots(idx, N);
  let inner = '';

  switch(slide.type) {
    case 'cover':
      const wrapLine = (text, isGrad) => {
        if (!text) return '';
        const wordCount = text.trim().split(/\s+/).length;
        const doStretch = isGrad && wordCount === 1;
        const stretchArabic = (w) => {
          const chars = Array.from(w);
          const out = [];
          for (let i = 0; i < chars.length; i++) {
            out.push(chars[i]);
            const c = chars[i];
            const next = chars[i+1];
            if (next && /[\u0600-\u06FF]/.test(c) && /[\u0600-\u06FF]/.test(next) && !/[\u0621\u0622\u0623\u0624\u0625\u0626\u0627\u062F\u0630\u0631\u0632\u0648\u0629]/.test(c)) {
              out.push('\u0640\u0640\u0640');
            }
          }
          return out.join('');
        };
        const displayText = doStretch ? stretchArabic(text) : text;
        const didStretch = doStretch && displayText !== text;
        if (isGrad) return '<span class="grad' + (didStretch ? ' stretched' : '') + '">' + displayText + '</span>';
        return didStretch ? '<span class="stretched">' + displayText + '</span>' : displayText;
      };
      const titleLine2 = slide.title_line2_grad ? wrapLine(slide.title_line2_grad, true) : '';
      inner = '<div class="content">' +
        '<div class="eyebrow">' + (slide.eyebrow||'') + '</div>' +
        '<div class="title">' +
          wrapLine(slide.title_line1, false) + (slide.title_line1 ? '<br>' : '') +
          titleLine2 + (slide.title_line2_grad && slide.title_line3 ? '<br>' : '') +
          wrapLine(slide.title_line3, false) +
        '</div>' +
        '<div class="pill">' + (slide.pill||'') + '</div>' +
        '<div class="arrow-btn"><svg width="55" height="55" viewBox="0 0 24 24" fill="none" stroke="#9B5CF6" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12H19"/><path d="M12 5l7 7-7 7"/></svg></div>' +
      '</div>';
      break;

    case 'stat':
      inner = '<div class="content">' +
        '<div class="big-number grad">' + (slide.number||'') + '</div>' +
        '<div class="label">' + (slide.label||'') + '</div>' +
        '<div class="desc">' + (slide.description||'') + '</div>' +
        '<div class="emoji-big">' + (slide.emoji||'') + '</div>' +
      '</div>';
      break;

    case 'why_matters':
      const wmPoints = (slide.points||[]).map((p, i) =>
        '<div class="step"><div class="bullet">' + ['١','٢','٣','٤','٥','٦'][i] + '</div><div class="step-text">' + p + '</div></div>'
      ).join('');
      inner = '<div class="content" style="align-items:flex-start;">' +
        '<div class="section-title grad">' + (slide.title||'ليش يهمك؟') + '</div>' +
        wmPoints +
      '</div>';
      break;

    case 'how_to':
      const htSteps = (slide.steps||[]).map((s, i) =>
        '<div class="step"><div class="bullet">' + ['١','٢','٣','٤','٥','٦'][i] + '</div><div class="step-text">' + s + '</div></div>'
      ).join('');
      inner = '<div class="content" style="align-items:flex-start;">' +
        '<div class="section-title grad">' + (slide.title||'كيف تستفيد؟') + '</div>' +
        htSteps +
      '</div>';
      break;

    case 'save':
      const saveRows = (slide.points||[]).map((p, i) =>
        '<div class="save-row"><div class="bullet">' + (['١','٢','٣','٤','٥','٦','٧','٨'][i] || (i+1)) + '</div><div class="step-text">' + p + '</div></div>'
      ).join('');
      inner = '<div class="content" style="align-items:flex-start;">' +
        '<div class="save-label">🔖 احفظ هذا السلايد</div>' +
        '<div class="save-box">' + saveRows + '</div>' +
      '</div>';
      break;

    case 'one_liner':
      const olText = slide.grad_word ?
        (slide.text||'').replace(slide.grad_word, '<span class="grad">' + slide.grad_word + '</span>') :
        (slide.text||'');
      inner = '<div class="content"><div class="one-liner-text">' + olText + '</div></div>';
      break;

    case 'comparison':
      const rows = (slide.rows||[]).map(r =>
        '<div class="comp-row"><div class="comp-cell">' + r[0] + '</div><div class="comp-cell">' + r[1] + '</div></div>'
      ).join('');
      inner = '<div class="content">' +
        '<div class="comparison-table">' +
          '<div class="comp-header"><div class="comp-col-header grad">' + (slide.col1_header||'') + '</div><div class="comp-col-header grad">' + (slide.col2_header||'') + '</div></div>' +
          rows +
        '</div></div>';
      break;

    case 'quote':
      inner = '<div class="content">' +
        '<div class="quote-mark">"</div>' +
        '<div class="quote-text">' + (slide.quote||'') + '</div>' +
        '<div class="quote-author">' + (slide.author||'') + ' — ' + (slide.role||'') + '</div>' +
      '</div>';
      break;

    case 'warning':
      const wPoints = (slide.points||[]).map(p =>
        '<div class="warning-point">⚠️ ' + p + '</div>'
      ).join('');
      inner = '<div class="content" style="align-items:flex-start;">' +
        '<div class="warning-icon">⚠️</div>' +
        '<div class="warning-title grad">' + (slide.title||'انتبه!') + '</div>' +
        '<div class="warning-points">' + wPoints + '</div>' +
      '</div>';
      break;

    case 'action_prompt': {
      const ACTION_EMOJI = {
        'share': '📤',
        'save':  '🔖',
        'like':  '❤️'
      };
      const emoji = ACTION_EMOJI[slide.action] || ACTION_EMOJI['save'];
      const DEFAULT_HEADLINES = {
        'save':  'احفظ هالمنشور يمكن ما تحصله',
        'share': 'حق منو راح ترسل هذا البوست؟',
        'like':  'اضغط مرتين عالشاشة'
      };
      const headline = slide.headline || DEFAULT_HEADLINES[slide.action] || DEFAULT_HEADLINES['save'];
      inner = '<div style="position:absolute;top:140px;left:0;right:0;z-index:2;padding:0 60px;text-align:center">' +
        '<div style="font-size:62px;font-weight:900;color:#fff;line-height:1.4;max-width:900px;margin:0 auto;text-shadow:0 4px 20px rgba(0,0,0,0.8)">' + headline + '</div>' +
      '</div>' +
      '<div style="position:absolute;bottom:150px;left:0;right:0;text-align:center;font-size:360px;line-height:1;z-index:1">' + emoji + '</div>';
      break;
    }
    case 'cta':
      let ctaContent = '';
      const q = slide.grad_phrase ?
        (slide.question||'').replace(slide.grad_phrase, '<span class="grad">' + slide.grad_phrase + '</span>') :
        (slide.question||'');

      if (slide.cta_style === 'options' && slide.options) {
        const classes = ['a','b','c'];
        const optHtml = slide.options.map((o, i) =>
          '<div class="option ' + (classes[i]||'c') + '">' + o + '</div>'
        ).join('');
        ctaContent = '<div class="options">' + optHtml + '</div>';
      } else if (slide.cta_style === 'poll') {
        ctaContent = '<div class="options"><div class="option a">' + (slide.poll_left||'موافق') + ' ←</div><div class="option b">→ ' + (slide.poll_right||'مو موافق') + '</div></div>';
      } else if (slide.cta_style === 'open') {
        ctaContent = '<div class="desc" style="font-size:52px;line-height:1.7;">💬 شاركنا جوابك بالكومنت</div>';
      } else if (slide.cta_style === 'share') {
        ctaContent = '<div class="options"><div class="option a">📤 شارك مع صديق</div><div class="option b">🔖 احفظ للرجوع له</div></div>';
      } else if (slide.cta_style === 'follow') {
        ctaContent = '<div class="options"><div class="option a">✅ تابعني عشان ما تفوتك</div></div>';
      } else if (slide.cta_style === 'challenge') {
        ctaContent = '<div class="desc" style="font-size:52px;line-height:1.7;">🎯 جرّبه وقولنا النتيجة بالكومنت</div>';
      } else {
        ctaContent = '<div class="desc" style="font-size:52px;line-height:1.7;">💬 شاركنا رأيك بالكومنت</div>';
      }

      inner = '<div class="content">' +
        '<div class="question">' + q + '</div>' +
        ctaContent +
        '<div class="profile">' +
          '<div class="photo-circle"><img src="' + MAJED_PHOTO + '" alt="Majed"></div>' +
          '<div class="profile-name" style="direction:ltr">@majedphotos ✓</div>' +
        '</div>' +
      '</div>';
      break;

    default:
      inner = '<div class="content"><div class="desc">Unknown slide type: ' + slide.type + '</div></div>';
  }

  return '<div class="slide">' + common + inner + '</div>';
}

let slidesHtml = slides.map((s, i) => renderSlide(s, i)).join('\n');

const captionHtml = data.caption ?
  '<div class="caption-area"><h3>📝 الكابشن</h3><p>' + data.caption + '</p><div class="hashtags">' + (data.hashtags||'') + '</div></div>' : '';

const fullHtml = '<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;700;900&display=swap" rel="stylesheet"><title>Carousel Preview — ' + data.topic + '</title><style>' + CSS + '</style></head><body><div class="slides-container">' + slidesHtml + '</div>' + captionHtml + '</body></html>';

const buffer = Buffer.from(fullHtml, 'utf-8');
return [{
  json: {},
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'carousel_preview.html',
      fileExtension: 'html'
    }
  }
}];

const items = $input.all();
let lastApproved = null;
for (let i = items.length - 1; i >= 0; i--) {
  if (items[i].json.status === 'approved') {
    lastApproved = items[i].json;
    break;
  }
}
if (!lastApproved) throw new Error('No approved rows found');
return [{ json: { ...lastApproved, contentJson: lastApproved['content'] } }];

let raw = $('Get Last Approved').item.json.contentJson;

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');

if (start === -1 || end === -1) {
  throw new Error('لم يتم العثور على JSON صالح داخل المحتوى المعتمد');
}

const data = JSON.parse(raw.substring(start, end + 1));
const slides = Array.isArray(data.slides) ? data.slides : [];

if (!slides.length) {
  throw new Error('لا توجد سلايدات داخل المحتوى المعتمد');
}

const N = slides.length;

/*
|--------------------------------------------------------------------------
| هوية فطين
|--------------------------------------------------------------------------
*/

const BRAND = {
  name: 'فطين',
  handle: '@playfateen',
  background: '#0B1F2A',
  backgroundSoft: '#102B38',
  cream: '#F7F2E8',
  white: '#FFFFFF',
  teal: '#36C2B4',
  coral: '#FF8364',
  yellow: '#F5C95B',
  muted: '#AFC1C7',
  darkText: '#10242E'
};

const episodeNumber =
  data.episode_number ||
  data.episode ||
  data.series_number ||
  '';

const arabicNums = ['١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩', '١٠'];

/*
|--------------------------------------------------------------------------
| أدوات حماية النصوص
|--------------------------------------------------------------------------
*/

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function cleanText(value = '') {
  return escapeHtml(String(value).trim());
}

function highlightWord(text = '', word = '') {
  const safeText = cleanText(text);
  const safeWord = cleanText(word);

  if (!safeWord || !safeText.includes(safeWord)) {
    return safeText;
  }

  return safeText.replace(
    safeWord,
    `<span class="highlight">${safeWord}</span>`
  );
}

function compactTextClass(text = '', base = 'body-text') {
  const length = String(text).length;

  if (length > 150) return `${base} extra-small`;
  if (length > 100) return `${base} small`;
  if (length > 65) return `${base} medium`;

  return base;
}

function pointsClass(points = []) {
  const totalLength = points.join('').length;

  if (points.length >= 5 || totalLength > 220) return 'point-text small';
  if (totalLength > 150) return 'point-text medium';

  return 'point-text';
}

/*
|--------------------------------------------------------------------------
| عناصر الهوية المشتركة
|--------------------------------------------------------------------------
*/

function brandHeader(idx) {
  const current = idx + 1;

  return `
    <div class="brand-header">
      <div class="brand-name">${BRAND.name}</div>

      <div class="slide-meta">
        ${
          episodeNumber
            ? `<span class="episode-number">${cleanText(episodeNumber)}</span>`
            : ''
        }

        <span class="slide-number">${current}</span>
      </div>
    </div>
  `;
}

function swipeHint(idx) {
  if (idx === N - 1) return '';

  return `
    <div class="swipe-hint">
      <span>اسحب</span>
      <svg
        width="30"
        height="30"
        viewBox="0 0 24 24"
        fill="none"
        aria-hidden="true"
      >
        <path
          d="M15 18L9 12L15 6"
          stroke="currentColor"
          stroke-width="2.6"
          stroke-linecap="round"
          stroke-linejoin="round"
        />
      </svg>
    </div>
  `;
}

function footerProgress(idx) {
  let bars = '';

  for (let i = 0; i < N; i++) {
    bars += `
      <span class="progress-segment ${i <= idx ? 'active' : ''}"></span>
    `;
  }

  return `
    <div class="footer-progress">
      ${bars}
    </div>
  `;
}

function decorativeShapes(variant = 'default') {
  if (variant === 'cover') {
    return `
      <div class="shape glow-one"></div>
      <div class="shape glow-two"></div>
      <div class="orbit orbit-one"></div>
      <div class="orbit orbit-two"></div>
      <div class="spark spark-one">✦</div>
      <div class="spark spark-two">✦</div>
    `;
  }

  if (variant === 'light') {
    return `
      <div class="shape light-orb-one"></div>
      <div class="shape light-orb-two"></div>
    `;
  }

  return `
    <div class="shape soft-orb-one"></div>
    <div class="shape soft-orb-two"></div>
  `;
}

/*
|--------------------------------------------------------------------------
| صورة ChatGPT الاختيارية
|--------------------------------------------------------------------------
|
| لاحقًا عندما تولد صورة من OpenAI، ضع رابطها داخل أحد الحقول:
| image_url
| visual_url
| background_image
|
*/

function generatedVisual(slide, mode = 'card') {
  const url =
    slide.image_url ||
    slide.visual_url ||
    slide.background_image ||
    '';

  if (!url) return '';

  const safeUrl = escapeHtml(url);

  if (mode === 'background') {
    return `
      <div
        class="generated-background"
        style="background-image:url('${safeUrl}')"
      ></div>
      <div class="generated-overlay"></div>
    `;
  }

  return `
    <div class="visual-card">
      <img
        src="${safeUrl}"
        alt=""
        crossorigin="anonymous"
      />
    </div>
  `;
}

/*
|--------------------------------------------------------------------------
| المكوّنات
|--------------------------------------------------------------------------
*/

function numberedPoints(points = []) {
  const pointTextClass = pointsClass(points);

  return points
    .map((point, index) => {
      return `
        <div class="point-row">
          <div class="point-number">
            ${arabicNums[index] || index + 1}
          </div>

          <div class="${pointTextClass}">
            ${cleanText(point)}
          </div>
        </div>
      `;
    })
    .join('');
}

function iconForType(type = '') {
  const icons = {
    stat: '↗',
    why_matters: '!',
    how_to: '✓',
    save: '⌁',
    one_liner: '✦',
    comparison: '⇄',
    quote: '“',
    warning: '!',
    action_prompt: '✦',
    cta: '?'
  };

  return icons[type] || '✦';
}

function typeLabel(type = '') {
  const labels = {
    stat: 'رقم يستحق الوقوف عنده',
    why_matters: 'ليش هذا مهم؟',
    how_to: 'كيف تستفيد؟',
    save: 'معلومات تستحق الحفظ',
    one_liner: 'الخلاصة',
    comparison: 'خلنا نقارن',
    quote: 'كلام يستحق الانتباه',
    warning: 'انتبه',
    action_prompt: 'قبل تكمل',
    cta: 'شاركنا'
  };

  return labels[type] || 'معلومة فطينة';
}

function sectionBadge(type = '') {
  return `
    <div class="section-badge">
      <span class="section-icon">${iconForType(type)}</span>
      <span>${typeLabel(type)}</span>
    </div>
  `;
}

/*
|--------------------------------------------------------------------------
| تصميم كل نوع سلايد
|--------------------------------------------------------------------------
*/

function renderCover(slide) {
  const title1 = cleanText(slide.title_line1 || '');
  const title2 = cleanText(slide.title_line2_grad || '');
  const title3 = cleanText(slide.title_line3 || '');

  const fullTitleLength =
    String(slide.title_line1 || '').length +
    String(slide.title_line2_grad || '').length +
    String(slide.title_line3 || '').length;

  let titleClass = 'cover-title';

  if (fullTitleLength > 70) titleClass += ' small';
  else if (fullTitleLength > 48) titleClass += ' medium';

  const isStretched =
    slide.stretched === true ||
    slide.cover_style === 'stretched';

  return `
    ${generatedVisual(slide, 'background')}
    ${decorativeShapes('cover')}

    <main class="cover-content">
      ${
        slide.eyebrow
          ? `
            <div class="eyebrow">
              ${cleanText(slide.eyebrow)}
            </div>
          `
          : ''
      }

      <div class="${titleClass}">
        ${title1 ? `<div>${title1}</div>` : ''}

        ${
          title2
            ? `
              <div class="cover-highlight ${isStretched ? 'stretched' : ''}">
                ${title2}
              </div>
            `
            : ''
        }

        ${title3 ? `<div>${title3}</div>` : ''}
      </div>

      ${
        slide.pill
          ? `
            <div class="cover-pill">
              ${cleanText(slide.pill)}
            </div>
          `
          : ''
      }

      ${generatedVisual(slide)}
    </main>
  `;
}

function renderStat(slide) {
  return `
    ${decorativeShapes()}

    <main class="center-content">
      ${sectionBadge('stat')}

      <div class="stat-number">
        ${cleanText(slide.number || '')}
      </div>

      <div class="stat-label">
        ${cleanText(slide.label || '')}
      </div>

      ${
        slide.description
          ? `
            <div class="${compactTextClass(slide.description)}">
              ${cleanText(slide.description)}
            </div>
          `
          : ''
      }

      ${
        slide.emoji
          ? `
            <div class="stat-emoji">
              ${cleanText(slide.emoji)}
            </div>
          `
          : ''
      }

      ${generatedVisual(slide)}
    </main>
  `;
}

function renderWhyMatters(slide) {
