}

function renderActionPrompt(slide) {
  const action = slide.action || 'save';

  const defaults = {
    save: {
      icon: '⌁',
      title: 'احفظ المنشور',
      subtitle: 'يمكن تحتاجه بعدين'
    },
    share: {
      icon: '↗',
      title: 'شارك المنشور',
      subtitle: 'يمكن يفيد شخص تعرفه'
    },
