      icon: '♡',
      title: 'عجبك المحتوى؟',
      subtitle: 'اضغط مرتين على الشاشة'
    }
  };

  const chosen = defaults[action] || defaults.save;

  return `
    ${generatedVisual(slide, 'background')}
    ${decorativeShapes('cover')}

    <main class="action-content">
      <div class="action-icon">
        ${chosen.icon}
      </div>

      <div class="action-headline">
        ${cleanText(slide.headline || chosen.title)}
      </div>

      <div class="action-subtitle">
        ${chosen.subtitle}
      </div>

      <div class="brand-stamp">
        <span>${BRAND.name}</span>
        <small>معلومة تستاهل تنتشر</small>
      </div>
    </main>
  `;
}

function renderCTA(slide) {
  const question = highlightWord(
    slide.question || 'وش أكثر شيء فاجأك؟',
    slide.grad_phrase || ''
  );

  let interaction = '';

  if (
    slide.cta_style === 'options' &&
    Array.isArray(slide.options) &&
    slide.options.length
  ) {
    interaction = `
      <div class="cta-options">
        ${slide.options
          .slice(0, 3)
          .map((option, index) => {
            const letters = ['A', 'B', 'C'];

            return `
              <div class="cta-option">
                <span>${letters[index]}</span>
                <div>${cleanText(option)}</div>
              </div>
            `;
          })
          .join('')}
      </div>
    `;
  } else if (slide.cta_style === 'poll') {
    interaction = `
      <div class="poll-options">
        <div class="poll-option yes">
          ${cleanText(slide.poll_left || 'موافق')}
        </div>

        <div class="poll-option no">
          ${cleanText(slide.poll_right || 'مو موافق')}
        </div>
      </div>
    `;
  } else if (slide.cta_style === 'share') {
    interaction = `
      <div class="cta-message">
        أرسلها للشخص اللي لازم يعرف
      </div>
    `;
  } else if (slide.cta_style === 'follow') {
    interaction = `
      <div class="cta-message">
        تابع فطين للمعلومة الجاية
      </div>
    `;
  } else if (slide.cta_style === 'challenge') {
    interaction = `
      <div class="cta-message">
        جرّبها وارجع خبرنا بالنتيجة
      </div>
    `;
  } else {
    interaction = `
      <div class="cta-message">
        اكتب جوابك في التعليقات
      </div>
    `;
  }

  return `
    ${decorativeShapes('cover')}

    <main class="cta-content">
      <div class="cta-mini-label">
        دورك الحين
      </div>

      <div class="cta-question">
        ${question}
      </div>

      ${interaction}

      <div class="fateen-signature">
        <div class="fateen-logo">${BRAND.name}</div>
        <div class="fateen-tagline">
          ثقافتك لعبة.. والفوز لمن كان فطينًا
        </div>
      </div>
    </main>
  `;
}

/*
|--------------------------------------------------------------------------
| اختيار التصميم المناسب
|--------------------------------------------------------------------------
*/

function renderSlideInner(slide, idx) {
  switch (slide.type) {
    case 'cover':
      return renderCover(slide);

    case 'stat':
      return renderStat(slide);

    case 'why_matters':
      return renderWhyMatters(slide);

    case 'how_to':
      return renderHowTo(slide);

    case 'save':
      return renderSave(slide);

    case 'one_liner':
      return renderOneLiner(slide);

    case 'comparison':
      return renderComparison(slide);

    case 'quote':
      return renderQuote(slide);

    case 'warning':
      return renderWarning(slide);

    case 'action_prompt':
      return renderActionPrompt(slide);

    case 'cta':
      return renderCTA(slide);

    default:
      return `
        <main class="center-content">
          <div class="unknown-type">
            نوع السلايد غير معروف:
            ${cleanText(slide.type || '')}
          </div>
        </main>
      `;
  }
}

